/* 独立HTML绑定任务数据；业务命令统一走维护模拟接口。 */
(async()=>{if(!document.getElementById('mt-items'))return;const $=id=>document.getElementById(id),api=EamMaintenanceApi,ui=EamUiComponents,q=new URLSearchParams(location.search),id=q.get('id'),path='/maintenance/tasks/'+encodeURIComponent(id||'');let task,config,safety,busy=false,dirty=false,command,itemId,key,linkPage=1,auditPage=1;const names={assign:'指派 / 改派人员',start:'安全确认并开工',pause:'暂停执行',resume:'复核并恢复',cancel:'取消未开工任务',submit:'提交完工待验收',discoveries:'上报保养异常'};
const person=id=>[...config.people,...config.followupPeople].find(p=>p.id===id)?.name||id||'待指派';
function rows(tbody,pager,items,p,onChange){$(tbody).replaceChildren();for(const values of items.slice((p-1)*5,p*5)){const tr=document.createElement('tr');for(const value of values){const td=document.createElement('td');if(value instanceof Node)td.append(value);else{td.textContent=value;td.title=value;}tr.append(td);}$(tbody).append(tr);}ui.decorateTables();ui.setTableStatus(tbody,'loaded');ui.pagination($(pager),{page:p,pages:Math.max(1,Math.ceil(items.length/5)),total:items.length,pageSize:5,onChange});}
function bind(){document.title=task.name+' · 保养任务';$('mt-title').textContent=task.name;$('mt-state').textContent=config.taskStates.find(s=>s.id===task.status)?.name;$('mt-summary').replaceChildren();for(const [label,value]of [['任务编号',task.code],['设备',config.equipment.find(e=>e.id===task.equipmentId)?.name||task.equipmentId],['来源计划',task.snapshot.code+' · 发布V'+task.planVersion],['执行窗口',task.windowStart+' 至 '+task.windowEnd],['主责人员',person(task.primaryPersonId)],['协作人员',task.collaboratorIds.map(person).join('、')||'无'],['版本','数据V'+task.revision+' / 执行V'+task.executionVersion]]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.className='col-4 col-md-2 text-secondary';dd.className='col-8 col-md-4';dt.textContent=label;dd.textContent=value;$('mt-summary').append(dt,dd);}$('mt-actions').replaceChildren();for(const [action,label]of Object.entries(names))if(task.actions[action]&&action!=='discoveries'){const b=document.createElement('button');b.className='btn btn-sm '+(action==='start'||action==='submit'?'btn-primary':'btn-outline-secondary');b.textContent=label;b.onclick=()=>open(action);$('mt-actions').append(b);}$('mt-boundary').textContent=task.status==='pending_acceptance'?'本次提交已冻结，等待独立验收。关联异常仍由异常事件中心处置。':task.status==='completed'?'独立验收已通过，保养任务完成；关联异常及使用限制仍需各自闭环。':task.status==='terminated'?'终止已获独立批准；遗留风险和后续安排见审核记录。':task.termination?.status==='pending_review'?'终止申请待独立审核，执行与改派已冻结。':task.returnReason?'验收退回：'+task.returnReason+'；当前为新执行版本，需重新安全复核后重做。':['in_progress','paused'].includes(task.status)?'已开工任务仅可申请终止，不能直接取消。':task.status==='cancelled'?'取消原因：'+task.cancelReason:'计划修订不会覆盖本任务快照。';$('mt-items').replaceChildren();for(const item of task.snapshot.items){const node=$('mt-item-template').content.firstElementChild.cloneNode(true),result=task.execution.results.find(r=>r.itemId===item.id)||{};node.dataset.item=item.id;node.querySelector('[data-item-name]').textContent=item.name+(item.required?' · 必填':' · 可选');node.querySelector('[data-item-standard]').textContent=[item.part,item.method,item.criterion,item.resultType==='number'?item.min+'～'+item.max+' '+item.unit:''].filter(Boolean).join(' / ');node.querySelector('[data-number-label]').hidden=item.resultType!=='number';for(const el of node.querySelectorAll('[data-field]'))el.value=result[el.dataset.field]??'';node.querySelector('[data-item-actor]').textContent=result.actorId?'记录人 '+person(result.actorId)+' · '+EamProduct.time(result.recordedAt):'尚未记录';const b=node.querySelector('[data-report]');b.hidden=!task.actions.discoveries;b.onclick=()=>open('discoveries',item.id);$('mt-items').append(node);}$('mt-labor').value=task.execution.laborMinutes??'';$('mt-material').value=task.execution.materialRef||'';$('mt-trial').value=task.execution.trial||'';$('mt-execution-fields').disabled=!task.actions.save;$('mt-save').hidden=!task.actions.save;$('mt-load').textContent='已读取任务 · 数据V'+task.revision;dirty=false;drawLinks();drawAudit();EamMaintenanceClosureUi.bind(task,config,updated=>{task=updated;bind();refreshSafety();},()=>dirty||busy);}
function drawLinks(){rows('mt-links','mt-links-pagination',task.anomalyLinks.map(l=>{const b=document.createElement('button');b.className='btn btn-sm btn-outline-primary';b.textContent=l.status==='linked'?'查看发现':'重试关联';b.disabled=l.status!=='linked'&&!task.actions.discoveries;b.onclick=()=>l.status==='linked'?Eam.go('abnormal-events',{equipment:task.equipmentId,id:l.discoveryId}):retry(l);return [task.snapshot.items.find(i=>i.id===l.itemId)?.name||l.itemId,l.discoveryId||'尚未创建',({linked:'已关联',failed:'待重试',pending_link:'关联中'})[l.status],l.error||'发现待核实分诊',b];}),linkPage,p=>{linkPage=p;drawLinks();});}
function drawAudit(){rows('mt-audit','mt-audit-pagination',[...task.audit].reverse().map(a=>[EamProduct.time(a.at),person(a.actorId),names[a.action]||config.taskActionLabels[a.action]||({generate:'计划生成',execution:'暂存执行',retry_link:'重试关联'})[a.action]||a.action,a.reason]),auditPage,p=>{auditPage=p;drawAudit();});}
async function refreshSafety(){try{safety=await api.request('GET',path+'/start-check');$('mt-safety').replaceChildren();for(const c of safety.checks){const div=document.createElement('div');div.className='col-sm-6 small';const badge=document.createElement('span');badge.className='badge me-2 '+(c.passed?'text-bg-success':'text-bg-warning');badge.textContent=c.passed?'通过':'未通过';div.append(badge,document.createTextNode(c.label));$('mt-safety').append(div);}$('mt-permit').textContent=safety.permit?'许可 '+safety.permit.id+' · '+safety.permit.controls.join(' / ')+' · 检查日期 '+safety.checkedOn:'无当前有效专业许可';}catch(e){$('mt-permit').textContent=e.message;safety=null;}}
async function open(action,item){if(busy)return;if(dirty){Eam.message('请先暂存执行记录，再执行状态操作');return;}command=action;itemId=item;key=crypto.randomUUID();$('mt-command-form').reset();$('mt-command-error').textContent='';$('mt-command-title').textContent=names[action];$('mt-assignment-fields').hidden=action!=='assign';$('mt-start-fields').hidden=!['start','resume'].includes(action);$('mt-discovery-fields').hidden=action!=='discoveries';$('mt-reason-label').hidden=action==='start'||action==='discoveries';$('mt-reason').required=!$('mt-reason-label').hidden;$('mt-description').required=action==='discoveries';$('mt-occurred').required=action==='discoveries';$('mt-confirmed').required=['start','resume'].includes(action);if(action==='assign'){$('mt-primary').replaceChildren(new Option('请选择主责',''));$('mt-collaborators').replaceChildren();for(const p of task.candidatePeople){$('mt-primary').add(new Option(p.name,p.id));const label=document.createElement('label'),box=document.createElement('input');label.className='form-check';box.className='form-check-input';box.type='checkbox';box.value=p.id;box.checked=task.collaboratorIds.includes(p.id);label.append(box,document.createTextNode(p.name));$('mt-collaborators').append(label);}$('mt-primary').value=task.primaryPersonId;}$('mt-primary').required=action==='assign';if(['start','resume'].includes(action)){await refreshSafety();$('mt-command-safety').textContent=safety?.allowed?'许可 '+safety.permit.id+'：'+safety.permit.controls.join('；'):'当前安全检查未通过，无法提交';$('mt-command-submit').disabled=!safety?.allowed;}else $('mt-command-submit').disabled=false;if(action==='discoveries'){const date=new Date();$('mt-occurred').value=new Date(+date-date.getTimezoneOffset()*60000).toISOString().slice(0,16);}$('mt-command-dialog').showModal();}
const payload=()=>({expectedRevision:task.revision,executionVersion:task.executionVersion,results:[...$('mt-items').children].map(node=>({itemId:node.dataset.item,...Object.fromEntries([...node.querySelectorAll('[data-field]')].map(el=>[el.dataset.field,el.value]))})),laborMinutes:Number($('mt-labor').value),materialRef:$('mt-material').value,trial:$('mt-trial').value});
$('mt-execution-form').addEventListener('input',()=>dirty=true);$('mt-execution-form').addEventListener('change',()=>dirty=true);$('mt-execution-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('mt-save').disabled=true;try{task=await api.request('PATCH',path+'/execution',payload());bind();$('mt-error').textContent='';Eam.message('执行记录已暂存');}catch(e){$('mt-error').textContent=e.message+'；输入已保留';}finally{busy=false;$('mt-save').disabled=false;}};
$('mt-command-cancel').onclick=()=>$('mt-command-dialog').close();$('mt-command-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('mt-command-submit').disabled=true;try{const body={expectedRevision:task.revision,executionVersion:task.executionVersion,reason:$('mt-reason').value};if(command==='assign')Object.assign(body,{primaryPersonId:$('mt-primary').value,collaboratorIds:[...$('mt-collaborators').querySelectorAll('input:checked')].map(e=>e.value)});if(['start','resume'].includes(command))Object.assign(body,{confirmed:$('mt-confirmed').checked,permitId:safety?.permit?.id});if(command==='discoveries')Object.assign(body,{itemId,description:$('mt-description').value,evidence:$('mt-evidence').value,priority:$('mt-priority').value,occurredAt:new Date($('mt-occurred').value).toISOString(),idempotencyKey:key});task=await api.request('POST',path+'/'+command,body);$('mt-command-dialog').close();bind();await refreshSafety();if(task.anomalyLinks.some(l=>l.status!=='linked'))Eam.message('异常尚未完成关联，请在关联异常中重试');}catch(e){$('mt-command-error').textContent=e.message+'；输入已保留';}finally{busy=false;$('mt-command-submit').disabled=false;}};
async function retry(link){if(busy||dirty){Eam.message('请先暂存输入');return;}busy=true;try{task=await api.request('POST',path+'/anomaly-links/'+link.id+'/retry',{expectedRevision:task.revision,executionVersion:task.executionVersion});bind();}catch(e){$('mt-error').textContent=e.message;}finally{busy=false;}}
$('mt-safety-refresh').onclick=refreshSafety;
try{config=await api.request('GET','/maintenance/config');task=await api.request('GET',path);if(q.get('equipment')&&q.get('equipment')!==task.equipmentId)throw new Error('任务不属于当前设备范围');bind();await refreshSafety();}catch(e){$('mt-load').textContent=e.message;$('mt-actions').replaceChildren();$('mt-execution-fields').disabled=true;}})();
